/**
 * Lookup classical conjunction reading for 2 to 7 planets
 */
export function lookupParasharaConjunction(planets: string[]): ParasharaMultiPlanetConjunction | undefined {
  const key = [...planets].sort().join(',');
  return PARASHARA_LIGHT_CONJUNCTIONS[key];
}
